-- =====================================================================
-- Migration 002 (Phase 2 refinement): official garage, video posters and clip cards.
-- NON-DESTRUCTIVE and IDEMPOTENT: no DROP, no DELETE, no TRUNCATE. Safe to run more than once.
--   * creates media_vehicles only if it does not exist
--   * inserts or refreshes the five official vehicles (ids 9-13) and the new media rows with an upsert
--   * adds links with INSERT IGNORE
-- Run after 001. Apply with: python -m scripts.migrate_db --plan   then   python -m scripts.migrate_db
-- =====================================================================

CREATE TABLE IF NOT EXISTS media_vehicles (
    media_id    INT UNSIGNED NOT NULL,
    vehicle_id  INT UNSIGNED NOT NULL,
    PRIMARY KEY (media_id, vehicle_id),
    KEY ix_media_vehicles_vehicle (vehicle_id),
    CONSTRAINT fk_medv_media FOREIGN KEY (media_id)
        REFERENCES media_assets (media_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_medv_vehicle FOREIGN KEY (vehicle_id)
        REFERENCES vehicles (vehicle_id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

AS new ON DUPLICATE KEY UPDATE
    category_id = new.category_id, name = new.name, manufacturer = new.manufacturer, summary = new.summary,
    description = new.description, content_status = new.content_status, source_url = new.source_url,
    source_note = new.source_note;

AS new ON DUPLICATE KEY UPDATE
    title = new.title, media_type = new.media_type, intended_use = new.intended_use,
    source_url = new.source_url, embed_url = new.embed_url, attribution = new.attribution,
    usage_status = new.usage_status, approval_status = new.approval_status, notes = new.notes;


